#include <cstdio>

struct Point {
    int x;
    Point operator+(const Point& other) const { return {x + other.x}; }
};

struct Size {
    int x;
};

struct Gauge {
    explicit Gauge(int level);
};

Gauge gauge(1);

template <typename T>
int width(const T& shape) {
    return shape.x;
}

int main() {
    Point p{1};
    std::printf("%d", (p + p).x);
    return FROM_BUILD + EOF + width(p) + width(Size{2});
}
